{
  "data": {
    "extracted_information": "Información detallada sobre la API de Instagram Media Insights, incluyendo métricas disponibles, detalles de uso, autenticación, limitaciones y ejemplos de implementación.",
    "specifications": {
      "endpoint_lectura": "GET /v{API_VERSION}/{MEDIA_ID}/insights",
      "host_urls": {
        "instagram_api_con_instagram_login": "graph.instagram.com",
        "instagram_api_con_facebook_login": "graph.facebook.com"
      },
      "parametros_ruta": {
        "API_VERSION": "La versión de la API que usa su aplicación (ej. v23.0)",
        "MEDIA_ID": "ID del objeto Instagram Media (requerido)"
      },
      "parametros_query_string": {
        "access_token": "Token de acceso de usuario de Facebook o Instagram (requerido)",
        "breakdown": "Designa cómo desglosar los resultados en subconjuntos",
        "metric": "Lista de métricas separadas por comas que desea obtener (requerido)",
        "period": "Lista de períodos de tiempo separados por comas. Valores posibles: day, week, days_28, month, lifetime, total_over_range"
      },
      "autenticacion": {
        "tipos_de_acceso": {
          "instagram_api_con_instagram_login": {
            "tokens_acceso": "Token de acceso de usuario de Instagram",
            "tipo_login": "Business Login para Instagram",
            "permisos_requeridos": [
              "instagram_business_basic",
              "instagram_business_manage_insights"
            ]
          },
          "instagram_api_con_facebook_login": {
            "tokens_acceso": "Token de acceso de usuario de Facebook",
            "tipo_login": "Facebook Login para Business",
            "permisos_requeridos": [
              "instagram_basic",
              "instagram_manage_insights",
              "pages_read_engagement"
            ],
            "permisos_adicionales_si_rol_en_pagina": [
              "ads_management",
              "ads_read"
            ]
          }
        }
      },
      "sintaxis_respuesta": {
        "data": "Array de objetos que describen los resultados de la solicitud.",
        "name": "Nombre de la métrica.",
        "period": "Período solicitado (siempre 'lifetime').",
        "values": "Array de objetos con los valores de la métrica solicitada.",
        "value": "Valor de la métrica.",
        "title": "Título de la métrica.",
        "description": "Descripción de la métrica.",
        "total_value": "Objeto que describe los valores de desglose solicitados (si se solicitó).",
        "breakdowns": "Array de objetos que describen los desgloses solicitados y sus resultados.",
        "dimension_keys": "Array de strings que describen los desgloses solicitados.",
        "results": "Array de objetos que describen cada conjunto de desglose.",
        "dimension_values": "Array de strings que describen los valores del conjunto de desglose.",
        "id": "String que describe los parámetros de la ruta de la consulta."
      }
    },
    "features": {
      "metricas_disponibles": [
        {
          "nombre": "comments",
          "descripcion": "Número de comentarios en el objeto de medios.",
          "tipos_medios": ["FEED (posts)", "REELS"]
        },
        {
          "nombre": "follows",
          "descripcion": "El número de usuarios de Instagram que siguen la cuenta profesional de Instagram del usuario de la aplicación.",
          "tipos_medios": ["FEED (posts)", "STORY"]
        },
        {
          "nombre": "ig_reels_avg_watch_time",
          "descripcion": "La cantidad promedio de tiempo que se reprodujo el reel.",
          "tipos_medios": ["REELS"]
        },
        {
          "nombre": "ig_reels_video_view_total_time",
          "descripcion": "La cantidad total de tiempo que se reprodujo el reel, incluyendo cualquier tiempo de reproducción. (Métrica en desarrollo)",
          "tipos_medios": ["REELS"]
        },
        {
          "nombre": "likes",
          "descripcion": "Número de 'me gusta' en el objeto de medios.",
          "tipos_medios": ["FEED (posts)", "REELS"]
        },
        {
          "nombre": "navigation",
          "descripcion": "Número total de acciones tomadas desde su historia (exited, forward, back, next story).",
          "tipos_medios": ["STORY"],
          "desglose_disponible": "story_navigation_action_type"
        },
        {
          "nombre": "profile_activity",
          "descripcion": "Número de acciones que las personas realizan al visitar su perfil después de interactuar con su publicación.",
          "tipos_medios": ["FEED (posts)", "STORY"],
          "desglose_disponible": "action_type",
          "nota": "Disponible para medios creados después del 26 de octubre de 2017."
        },
        {
          "nombre": "profile_visits",
          "descripcion": "El número de veces que se visitó su perfil.",
          "tipos_medios": ["FEED (posts)", "STORY"]
        },
        {
          "nombre": "reach",
          "descripcion": "Número de usuarios únicos de Instagram que han visto el reel al menos una vez. (Métrica estimada)",
          "tipos_medios": ["FEED (posts)", "REELS", "STORY"]
        },
        {
          "nombre": "replies",
          "descripcion": "Número total de respuestas en el objeto IG Media de la historia. No incluye respuestas de usuarios en Europa (desde 1 dic 2020) y Japón (desde 14 abr 2021).",
          "tipos_medios": ["STORY"]
        },
        {
          "nombre": "saved",
          "descripcion": "Número de veces que el objeto de medios de Instagram del usuario de la aplicación fue guardado por un usuario de Instagram.",
          "tipos_medios": ["FEED (posts)", "REELS"]
        },
        {
          "nombre": "shares",
          "descripcion": "Número de veces que se compartió el reel.",
          "tipos_medios": ["FEED (posts)", "REELS", "STORY"]
        },
        {
          "nombre": "total_interactions",
          "descripcion": "Número de 'me gusta', guardados, comentarios y compartidos en el reel, menos los 'no me gusta', 'no guardados' y comentarios eliminados. (Métrica en desarrollo)",
          "tipos_medios": ["FEED (posts)", "REELS", "STORY"]
        },
        {
          "nombre": "views",
          "descripcion": "Número total de veces que se ha visto el video IG Media. (Métrica en desarrollo)",
          "tipos_medios": ["FEED (posts)", "REELS", "STORY"]
        }
      ],
      "metricas_deprecadas": [
        {
          "nombre": "clips_replays_count",
          "descripcion": "Número de veces que su reel comienza a reproducirse de nuevo después de una reproducción inicial. (Deprecada para v22.0 y para todas las versiones el 21 de abril de 2025)",
          "tipos_medios": ["REELS"]
        },
        {
          "nombre": "ig_reels_aggregated_all_plays_count",
          "descripcion": "Número de veces que su reel comienza a reproducirse o a reproducirse de nuevo después de que ya se haya contado una impresión. (Deprecada para v22.0 y para todas las versiones el 21 de abril de 2025)",
          "tipos_medios": ["REELS"]
        },
        {
          "nombre": "impressions",
          "descripcion": "Número total de veces que se ha visto el objeto Instagram Media del usuario de la aplicación. (Deprecada para v22.0+ para medios creados después del 2 de julio de 2024; disponible para medios creados antes del 2 de julio de 2024. Deprecación total el 21 de abril de 2025)",
          "tipos_medios": ["FEED (posts)", "STORY"]
        },
        {
          "nombre": "plays",
          "descripcion": "Número de veces que los reels comienzan a reproducirse después de que ya se haya contado una impresión. (Deprecada para v22.0 y para todas las versiones el 21 de abril de 2025)",
          "tipos_medios": ["REELS"]
        },
        {
          "nombre": "video_views",
          "descripcion": "Métrica 'video_views' ha sido deprecada."
        }
      ],
      "desgloses_disponibles": [
        {
          "valor": "action_type",
          "compatible_con": "profile_activity",
          "valores_respuesta": ["BIO_LINK_CLICKED", "CALL", "DIRECTION", "EMAIL", "OTHER", "TEXT"]
        },
        {
          "valor": "story_navigation_action_type",
          "compatible_con": "navigation",
          "valores_respuesta": ["SWIPE_FORWARD (Siguiente Historia)", "TAP_BACK (Atrás)", "TAP_EXIT (Salir)", "TAP_FORWARD (Adelante)"]
        }
      ]
    },
    "statistics": {},
    "temporal_info": {
      "almacenamiento_datos": "Datos de métricas almacenados hasta por 2 años.",
      "retraso_datos": "Los datos utilizados para calcular las métricas pueden retrasarse hasta 48 horas.",
      "disponibilidad_metricas_historias": "Las métricas de medios de historias solo están disponibles durante 24 horas. Los webhooks de 'story_insights' pueden proporcionar datos antes de que expiren."
    },
    "geographical_data": {
      "restricciones_respuestas": {
        "replies_europa_japon": "Para Historias creadas por usuarios en Europa y Japón, la métrica 'replies' devuelve un valor de 0. Las respuestas de usuarios en estas regiones no se incluyen en los cálculos de 'replies'."
      }
    },
    "references": [
      "https://developers.facebook.com/docs/instagram-platform/insights",
      "https://developers.facebook.com/docs/instagram-platform/reference/instagram-media#fields",
      "https://developers.facebook.com/docs/instagram-platform/changelog",
      "https://developers.facebook.com/docs/instagram-api/reference/ig-media",
      "https://developers.facebook.com/docs/instagram-api/guides/webhooks",
      "https://developers.facebook.com/docs/facebook-login/access-tokens/#usertokens",
      "https://developers.facebook.com/docs/permissions/reference#i",
      "https://developers.facebook.com/docs/instagram-api/overview#pages",
      "https://developers.facebook.com/docs/graph-api/guides/versioning",
      "https://business.facebook.com/business/help/metrics-labeling",
      "https://developers.facebook.com/docs/instagram-api/reference/ig-comment",
      "https://developers.facebook.com/docs/graph-api/results"
    }
  }
}
